    assert abs(-F_ * 3.7 / 1000 + 357) < 1 and abs(F_ / (3.6 * 97.87) - 273.8) < 0.1 and abs(F_ / (3.6 * 72.06) - 371.9) < 0.1
    assert abs(3.7 * 5 - 18.5) < 1e-9 and abs(18.5 / 0.07 - 264.3) < 0.1 and abs(3.7 * 96 - 355.2) < 1e-9 and abs(355.2 * 150 / 1000 - 53.28) < 1e-9
    assert 50 ** 2 * 0.002 == 5 and 100 - 0.02 * 1000 == 80 and abs(20 / 0.01 - 2000) < 1e-6


